// Zeigt die Trainerprofile mit Einsatzmengen. Aus der Admin-Ressource
// werden nur Name und Kurzzeichen ausgegeben, keine Kontakt- oder Adressdaten.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt.');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const basis = 'https://app1.edoobox.com/v2';

function rowsAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

async function holeAlle(pfad) {
  const alle = [];
  const reply = 2000;
  let start = 0;
  let total = null;
  for (let seite = 1; seite <= 20; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET', url: basis + pfad, headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true, returnFullResponse: true, timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
    if (!(a.statusCode >= 200 && a.statusCode < 300)) throw new Error(`${pfad}: HTTP ${a.statusCode}`);
    const rows = rowsAus(a.body);
    if (total === null && a.body?.limit?.total !== undefined) total = Number(a.body.limit.total);
    alle.push(...rows);
    start += rows.length;
    if (rows.length === 0 || rows.length < reply || (total !== null && start >= total)) break;
  }
  if (total !== null && alle.length !== total) throw new Error(`${pfad}: gemeldet ${total}, gelesen ${alle.length}`);
  return alle;
}

const admins = await holeAlle.call(this, '/admin/list');
const dates = await holeAlle.call(this, '/date/list');
const adminMap = new Map(admins.map(a => [String(a.id), a]));
const statistik = new Map();

for (const d of dates) {
  const leaders = [...new Set((Array.isArray(d.leader) ? d.leader : []).filter(Boolean).map(String))];
  for (const id of leaders) {
    const s = statistik.get(id) ?? {
      datumszeilen: 0,
      angebote: new Set(),
      erster: null,
      letzter: null,
    };
    s.datumszeilen += 1;
    if (d.offer) s.angebote.add(String(d.offer));
    const start = d.date_start ? String(d.date_start) : null;
    if (start && (!s.erster || start < s.erster)) s.erster = start;
    if (start && (!s.letzter || start > s.letzter)) s.letzter = start;
    statistik.set(id, s);
  }
}

const ids = new Set([...adminMap.keys(), ...statistik.keys()]);
const ausgabe = [...ids].map(id => {
  const a = adminMap.get(id);
  const s = statistik.get(id);
  const name = a ? [a.first_name, a.last_name].filter(Boolean).join(' ').trim() : '(historisches Profil)';
  return {
    json: {
      schritt: 'S55',
      admin_id: id,
      trainer: name || '(ohne Namen)',
      kuerzel: a?.shortcut || '-',
      admin_aktiv: a?.status === true,
      datumszeilen: s?.datumszeilen ?? 0,
      angebote: s?.angebote.size ?? 0,
      erster_einsatz: s?.erster ?? '-',
      letzter_einsatz: s?.letzter ?? '-',
      kostenrolle: 'noch festzulegen',
    },
  };
});

ausgabe.sort((x, y) => y.json.angebote - x.json.angebote || x.json.trainer.localeCompare(y.json.trainer));
return ausgabe;
